import React from "react";
import "./Offer.css";
import exclusive_img from "../Assets/hero_img2.png";

const Offer = () => {
  return (
    <section className="offer-container">
      <div className="offer-content">
        <div className="text-side">
          <h3 className="sub-title">Limited Time Offer</h3>
          <h1 className="main-title">Exclusive Deals Just for You</h1>
          <p className="description">Grab the best prices on our top-selling products.</p>

          <button className="offer-btn">Shop Now</button>
        </div>

        <div className="image-side">
          <img src={exclusive_img} alt="Exclusive Offer" />
        </div>
      </div>
    </section>
  );
};

export default Offer;
